    .mobile-nav-panel { display: none; position: fixed; inset: 62px 0 auto; z-index: 30; padding: 9px 14px 12px; background: white; border-bottom: 1px solid var(--line); box-shadow: 0 12px 25px rgba(42,20,32,.12); }
    .mobile-nav-panel.open { display: block; }
    .mobile-nav-panel .nav { display: flex; flex-wrap: wrap; gap: 9px; }
    .mobile-nav-panel .nav-item { width: auto; min-height: 0; flex: 0 0 auto; border: 1px solid var(--line); border-radius: 99px; padding: 7px 10px; background: white; color: var(--muted-plum); font-size: 9px; font-weight: 800; }
    .mobile-nav-panel .nav-item.active { color: var(--deep-magenta); background: var(--soft-blush); border-color: #EAC4D4; }
    .mobile-nav-panel .nav-count { min-width: 18px; height: 18px; font-size: 9px; }
  }
  @media (max-width: 540px) {
    .topbar-actions { gap: 7px; }
    .global-search { display: none; }
    .topbar { padding-inline: 11px; }
    .content { padding-inline: 11px; }
    .page-head { align-items: flex-start; flex-direction: column; gap: 12px; }
    .head-actions { width: 100%; }
    .head-actions .btn { flex: 1; }
    .stats { gap: 8px; }
    .stat-card { min-height: 107px; padding: 12px; }
    .stat-label { max-width: 90px; }
    .stat-number { font-size: 23px; }
    .appointment-row { grid-template-columns: 49px minmax(90px,1fr) auto; gap: 7px; }
    .appointment-row .appt-branch { display: none; }
    .service-grid { grid-template-columns: 1fr; }
    .form-grid { grid-template-columns: 1fr; }
    .form-field.full { grid-column: auto; }
    .footer-note { flex-direction: column; }
    .toast-wrap { left: 10px; right: 10px; top: 70px; }
  }
  @media (prefers-reduced-motion: reduce) { *,*::before,*::after { scroll-behavior: auto !important; animation-duration: .01ms !important; transition-duration: .01ms !important; } }
</style>
</head>
<body>
<div class="app" id="app" hidden>
  <aside class="sidebar" aria-label="Main navigation">
    <a class="brand" href="#overview" aria-label="EL Glamorous Face and Body Clinic admin home">
      <img id="brandLogo" alt="EL Glamorous Face and Body Clinic logo">
      <span class="workspace-label">Staff workspace</span>
    </a>
    <div class="nav-label">Workspace</div>
    <nav class="nav" id="sideNav">
      <button class="nav-item active" data-page="overview"><svg class="nav-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8"><rect x="3.5" y="3.5" width="7" height="7" rx="1.5"/><rect x="13.5" y="3.5" width="7" height="7" rx="1.5"/><rect x="3.5" y="13.5" width="7" height="7" rx="1.5"/><rect x="13.5" y="13.5" width="7" height="7" rx="1.5"/></svg>Overview</button>
      <button class="nav-item" data-page="bookings"><svg class="nav-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8"><rect x="3.5" y="5" width="17" height="15.5" rx="2"/><path d="M7.5 3.5v3M16.5 3.5v3M3.5 9.5h17M8 13h3M8 16.5h7"/></svg>Appointments <span class="nav-count" id="pendingCount">0</span></button>
      <button class="nav-item" data-page="inventory"><svg class="nav-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8"><path d="m4 7 8-4 8 4-8 4-8-4Z"/><path d="M4 7v10l8 4 8-4V7M12 11v10M8 5l8 4"/></svg>Inventory</button>
      <button class="nav-item" data-page="services"><svg class="nav-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8"><path d="M4 5.5h16M4 12h16M4 18.5h10"/><circle cx="7" cy="5.5" r="1.5" fill="white"/><circle cx="16" cy="12" r="1.5" fill="white"/><circle cx="10" cy="18.5" r="1.5" fill="white"/></svg>Service catalog</button>
      <button class="nav-item" data-page="branches"><svg class="nav-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8"><path d="M4 20.5V7.8L12 3l8 4.8v12.7H4Z"/><path d="M8 20.5v-5h8v5M8 9h.01M12 9h.01M16 9h.01M8 12h.01M16 12h.01" stroke-linecap="round"/></svg>Branches</button>
      <button class="nav-item" data-page="staff"><svg class="nav-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8"><circle cx="9" cy="8" r="3.5"/><path d="M3 20v-1a6 6 0 0 1 12 0v1M16 4.5a3.5 3.5 0 0 1 0 7M18 14a5 5 0 0 1 3 4.6V20"/></svg>Staff accounts</button>
    </nav>
    <div class="nav-label" id="officeLabel" hidden>Office</div>
    <nav class="nav" id="officeNav" aria-label="Office"></nav>
    <div class="sidebar-bottom">
      <div class="branch-status"><strong><span class="dot"></span>4 clinic branches</strong><p>Operations workspace</p></div>
      <div class="profile"><div class="avatar" id="profileInitials"></div><div><div class="profile-name" id="profileName"></div><div class="profile-role">Administrator</div></div><button class="sign-out" id="signOut" type="button">Sign out</button></div>
    </div>
  </aside>
  <div class="mobile-nav-panel" id="mobileNav" aria-label="Mobile navigation">
    <nav class="nav">
      <button class="nav-item active" data-page="overview">Overview</button>
      <button class="nav-item" data-page="bookings">Appointments <span class="nav-count" id="mobilePendingCount">0</span></button>
      <button class="nav-item" data-page="inventory">Inventory</button>
      <button class="nav-item" data-page="services">Service catalog</button>
      <button class="nav-item" data-page="branches">Branches</button>
      <button class="nav-item" data-page="staff">Staff accounts</button>
    </nav>
    <nav class="nav" id="mobileOfficeNav" aria-label="Office" style="margin-top:9px"></nav>
  </div>
  <main class="main">
    <header class="topbar">
      <div class="topbar-left">
        <button class="icon-button mobile-menu" id="menuButton" aria-label="Open navigation" aria-expanded="false"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M4 7h16M4 12h16M4 17h16"/></svg></button>
        <span class="mobile-brand">EL Glamorous Face and Body Clinic · Admin</span>
        <div class="crumb">Workspace <span aria-hidden="true">/</span> <strong id="breadcrumb">Overview</strong></div>
      </div>
      <div class="topbar-actions">
        <label class="global-search"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8"><circle cx="10.8" cy="10.8" r="6.8"/><path d="m16 16 4.2 4.2"/></svg><input id="globalSearch" type="search" placeholder="Search this page…" aria-label="Search current page"></label>
        <button class="icon-button" id="alertButton" aria-label="View inventory alerts"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8"><path d="M18 9a6 6 0 0 0-12 0c0 7-2.5 7-2.5 9h17C20.5 16 18 16 18 9ZM10 21h4"/></svg><span class="notification-dot"></span></button>
      </div>
    </header>
    <section class="content" id="pageContent" aria-live="polite"></section>
  </main>
</div>
<div class="modal-backdrop" id="modalBackdrop" role="presentation">
  <section class="modal" role="dialog" aria-modal="true" aria-labelledby="modalTitle" id="modal"></section>
</div>
<div class="toast-wrap" id="toastWrap" aria-live="polite" aria-atomic="true"></div>
<script src="../assets/office.js"></script>
<script>
  // The original logo was extracted from the supplied brand-reference PDF and embedded unchanged.
  const LOGO_DATA = 'data:image/png;base64,';
  document.getElementById('brandLogo').src = LOGO_DATA;

  let branches = [];
  const categoryIcons = {Face:'✧', Body:'◌', Hair:'⌁', Nails:'✿'};
  const today = new Date();
  const isoToday = localISO(today);
  function localISO(date) { const d = new Date(date.getTime() - date.getTimezoneOffset()*60000); return d.toISOString().slice(0,10); }
  function addDays(n) { const d = new Date(); d.setDate(d.getDate()+n); return localISO(d); }
  const API = '../../api';
  const LOGIN_URL = <?= json_encode(app_url(LOGIN_PAGE)) ?>;
  // Printed by the server from the signed-in session (see the guard at the top of this file).
  const CURRENT_USER = <?= user_json($user) ?>;
  const TIME_SLOTS = ['11:00 AM','12:30 PM','2:00 PM','3:30 PM','5:00 PM','6:30 PM'];
  const STATUSES = ['Pending','Confirmed','Completed','Cancelled','No-show'];
  let appointments = [];
  let serviceCatalog = [];
  let staffAccounts = [], permissionLabels = {};
  let inventory = [];
  let stockMovements = [];
  let dailySales = {total:0,count:0,byMethod:{},byCategory:{},byEmployee:{},commissionTotal:0,cardFeeTotal:0};
  let dailyExpenses = {total:0,byCategory:{}};
  let activePage = 'overview';
  let statusFilter = 'All statuses';
  let branchFilter = 'All branches';
  let inventoryBranchFilter = 'All branches';
  let searchTerm = '';
  const content = document.getElementById('pageContent');
  const icon = {
    search:'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8"><circle cx="10.8" cy="10.8" r="6.8"/><path d="m16 16 4.2 4.2"/></svg>',
    plus:'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M12 5v14M5 12h14"/></svg>',
    calendar:'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8"><rect x="3.5" y="5" width="17" height="15.5" rx="2"/><path d="M7.5 3.5v3M16.5 3.5v3M3.5 9.5h17"/></svg>',
    box:'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8"><path d="m4 7 8-4 8 4-8 4-8-4Z"/><path d="M4 7v10l8 4 8-4V7M12 11v10"/></svg>',
    clock:'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8"><circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/></svg>',
    check:'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8"><path d="m5 12 4.2 4.2L19 6.5"/></svg>',
    alert:'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8"><path d="M12 3.5 22 20H2L12 3.5Z"/><path d="M12 9v5M12 17.5h.01"/></svg>',
    pin:'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8"><path d="M20 10c0 5-8 11-8 11S4 15 4 10a8 8 0 1 1 16 0Z"/><circle cx="12" cy="10" r="2.5"/></svg>',
    phone:'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8"><path d="M7 3.5h3l1.5 4-2 1.5a15 15 0 0 0 5.5 5.5l1.5-2 4 1.5v3c0 1.1-.9 2-2 2C10.5 21 3 13.5 3 5.5c0-1.1.9-2 2-2h2Z"/></svg>'
  };
  function escapeHTML(value) { return String(value ?? '').replace(/[&<>"']/g, c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])); }
  function to24(label) { const m=String(label).match(/^(\d{1,2}):(\d\d)\s*(AM|PM)$/i); if(!m) return label; let h=Number(m[1])%12; if(m[3].toUpperCase()==='PM') h+=12; return `${String(h).padStart(2,'0')}:${m[2]}`; }
  async function api(path, options={}) {
    let res;
    try { res = await fetch(`${API}/${path}`, {credentials:'same-origin', ...options, headers: options.body ? {'Content-Type':'application/json'} : {}}); }
    catch { throw new Error('Can’t reach the clinic server. Check that XAMPP is running.'); }
    let data = {}; try { data = await res.json(); } catch {}
    if (res.status === 401 && !path.startsWith('auth.php')) window.location.replace(LOGIN_URL+'?notice=expired');
    if (!res.ok) { const err = new Error(data.error || 'Something went wrong. Please try again.'); err.status = res.status; throw err; }
    return data;
  }
  async function loadServices() { serviceCatalog=(await api('services.php?all=1')).services; }
  async function loadStaff() { const d=await api('staff.php'); staffAccounts=d.accounts; permissionLabels=d.permissions; }
  async function loadInventory() {
    const [{items}, {movements}] = await Promise.all([api('inventory.php?action=list'), api('inventory.php?action=movements')]);
    inventory = items.map(i=>({...i, id:String(i.id)}));
    stockMovements = movements;
  }
  async function loadAppointments() {
    const {bookings} = await api('bookings.php?action=list');
    appointments = bookings.map(b=>({id:b.id,name:b.name,phone:b.mobile,branch:b.branch,branchId:b.branchId,service:b.service,category:b.category,date:b.date,time:to24(b.time),status:b.status,source:b.source,paidAmount:b.paidAmount,paidMethod:b.paidMethod}));
  }
  function niceDate(date) { const d = new Date(date+'T12:00:00'); return new Intl.DateTimeFormat('en-PH',{weekday:'long',month:'long',day:'numeric',year:'numeric'}).format(d); }
  function timeLabel(t) { const [h,m]=t.split(':').map(Number); const ap=h>=12?'PM':'AM'; return `${h%12||12}:${String(m).padStart(2,'0')} ${ap}`; }
  function todayAppointments() { return appointments.filter(a=>a.date===isoToday); }
  function pendingAppointments() { return appointments.filter(a=>a.status==='Pending'); }
  function lowStock() { return inventory.filter(i=>Number(i.qty)<=Number(i.reorder)); }
  function badge(status) { return `<span class="status ${escapeHTML(status.toLowerCase())}">${escapeHTML(status)}</span>`; }
  function header(kicker,title,subtitle,actions='') { return `<div class="page-head"><div><p class="eyebrow">${kicker}</p><h1>${title}</h1><p class="page-subtitle">${subtitle}</p></div><div class="head-actions">${actions}</div></div>`; }
  function demoBanner(text='Appointments, inventory, treatments and branch details are live from the clinic database.') { return `<div class="demo-notice"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8"><circle cx="12" cy="12" r="9"/><path d="M12 11v5M12 8h.01"/></svg><span><strong>Preview only.</strong> ${text}</span></div>`; }
  function branchSelect(id, selected='All branches', includeAll=true) { return `<select id="${id}" aria-label="Filter by branch">${includeAll?'<option>All branches</option>':''}${branches.map(b=>`<option ${selected===b.name?'selected':''}>${escapeHTML(b.name)}</option>`).join('')}</select>`; }
  function statCard(label,value,foot,svg) { return `<article class="stat-card"><div class="stat-top"><div class="stat-label">${label}</div><div class="stat-icon">${svg}</div></div><div class="stat-number">${value}</div><div class="stat-foot">${foot}</div></article>`; }
  function appointmentRows(items,limit=null) {
    const sorted=[...items].sort((a,b)=>a.time.localeCompare(b.time));
    const shown=limit?sorted.slice(0,limit):sorted;
    if (!shown.length) return '<div class="empty-state"><b>No appointments found</b>Try changing your filters or add an appointment.</div>';
    return shown.map(a=>`<div class="appointment-row"><div class="appt-time">${timeLabel(a.time)}</div><div><div class="customer-name">${escapeHTML(a.name)}</div><div class="service-name">${escapeHTML(a.service)}</div></div><div class="appt-branch"><div class="branch-name">${escapeHTML(a.branch)} branch</div><div class="branch-name">${escapeHTML(a.phone)}</div></div><div>${badge(a.status)}</div></div>`).join('');
  }
  function renderOverview() {
    const todayList=todayAppointments();
    const waiting=todayList.filter(a=>a.status==='Pending').length;
    const done=todayList.filter(a=>a.status==='Completed').length;
    const cancelled=todayList.filter(a=>a.status==='Cancelled').length;
    const noShow=todayList.filter(a=>a.status==='No-show').length;
    const confirmed=todayList.filter(a=>a.status==='Confirmed').length;
    const salesTotal=Number(dailySales.total||0);
    const methodEntries=Object.entries(dailySales.byMethod||{}).sort((a,b)=>b[1]-a[1]).slice(0,3);
    const statusEntries=['Pending','Confirmed','Completed','Cancelled','No-show'].map(status=>({status,count:todayList.filter(a=>a.status===status).length})).filter(entry=>entry.count>0);
    const serviceCounts=todayList.reduce((map,a)=>{const key=(a.service||'General'); map[key]=(map[key]||0)+1; return map;},{});
    const topServices=Object.entries(serviceCounts).sort((a,b)=>b[1]-a[1]).slice(0,3);
    const revenueServices=Object.entries(dailySales.byService||{}).sort((a,b)=>b[1]-a[1]).slice(0,3);
    const revenueStaff=Object.entries(dailySales.byEmployee||{}).sort((a,b)=>b[1]-a[1]).slice(0,3);
    const lows=lowStock();
    const upcoming=appointments.filter(a=>a.date>=isoToday && a.status!=='Cancelled').sort((a,b)=>(a.date+a.time).localeCompare(b.date+b.time));
    const lowList=lows.slice(0,4);
    const branchSummary = branches.map(b=>{
      const count=todayList.filter(a=>a.branch===b.name).length;
      const lowCount=lows.filter(i=>i.branch===b.name).length;
      return `<article class="branch-mini"><div class="branch-mini-head"><h3>${escapeHTML(b.name)} branch</h3><span class="mini-pill">${count} today</span></div><p>${escapeHTML(b.area)} · ${lowCount ? `${lowCount} restock ${lowCount===1?'item':'items'}` : 'Stock healthy'}</p></article>`;
    });
    const branchPulse = branches.map(b=>{
      const count=todayList.filter(a=>a.branch===b.name).length;
      const maxCount=Math.max(1, ...branches.map(br=>todayList.filter(a=>a.branch===br.name).length));
      return `<div class="stock-row"><div class="stock-glyph">${escapeHTML(b.name.slice(0,1).toUpperCase())}</div><div class="stock-label"><b>${escapeHTML(b.name)}</b><span>${count} bookings today</span></div><div class="stock-qty"><span style="display:inline-block;width:${Math.max(32, (count / maxCount) * 100)}px;height:8px;border-radius:999px;background:linear-gradient(90deg,#d93f7b,#f7a7c4);vertical-align:middle;margin-right:8px"></span>${count}</div></div>`;
    }).join('');
    const lowInventoryRows = lowList.length ? lowList.map(item=>`<div class="stock-row"><div class="stock-glyph">${escapeHTML(item.name.slice(0,1).toUpperCase())}</div><div class="stock-label"><b>${escapeHTML(item.name)}</b><span>${escapeHTML(item.branch || 'All branches')} · reorder ${escapeHTML(String(item.reorder))}</span></div><div class="stock-qty">${escapeHTML(String(item.qty))}</div></div>`).join('') : '<div class="empty-state"><b>Stock looks healthy</b>All branch stock levels are above reorder points.</div>';
    const statusRows = statusEntries.length ? statusEntries.map(entry=>`<div class="stock-row"><div class="stock-glyph">${escapeHTML(entry.status.slice(0,1).toUpperCase())}</div><div class="stock-label"><b>${escapeHTML(entry.status)}</b><span>Bookings on today’s schedule</span></div><div class="stock-qty">${entry.count}</div></div>`).join('') : '<div class="empty-state"><b>No bookings yet</b>Appointments will appear here as they are made.</div>';
    return `${header('Clinic operations','Clinic overview',`A clear view of today across all ${branches.length || 4} branches · ${niceDate(isoToday)}`,`<button class="btn btn-primary" data-action="new-booking">${icon.plus} Add appointment</button>`)}
    ${demoBanner()}
    <div class="stats">
      ${statCard('Appointments today',todayList.length,`${branches.length || 4} branch coverage · ${done} completed`,icon.calendar)}
      ${statCard('Pending follow-up',waiting,`${confirmed} confirmed · ${cancelled} cancelled · ${noShow} no-show`,icon.clock)}
      ${statCard('Payments collected',Office.peso(salesTotal),`${dailySales.count||0} paid ${dailySales.count===1?'booking':'bookings'} today`,icon.check)}
      ${statCard('Low stock items',lows.length,`${lows.length ? `Review ${lows.length} restock ${lows.length===1?'item':'items'}` : 'Everything is within range'}`,icon.box)}
    </div>
    <div class="grid-main">
      <section class="panel"><div class="panel-head"><div><h2 class="panel-title">Today’s appointments</h2><p class="panel-sub">${todayList.length} bookings · all branches</p></div><button class="text-link" data-page="bookings">View all bookings →</button></div><div class="appointment-list">${appointmentRows(upcoming.filter(a=>a.date===isoToday),5)}</div></section>
      <section class="panel"><div class="panel-head"><div><h2 class="panel-title">Sales snapshot</h2><p class="panel-sub">Collected today · ${dailySales.count||0} payments</p></div><button class="text-link" data-page="office-sales">Open sales →</button></div><div class="low-stock-list">${methodEntries.length?methodEntries.map(([method,total])=>`<div class="stock-row"><div class="stock-glyph">${escapeHTML(method.slice(0,1).toUpperCase())}</div><div class="stock-label"><b>${escapeHTML(method)}</b><span>Paid by method</span></div><div class="stock-qty">${Office.peso(total)}</div></div>`).join(''):`<div class="empty-state"><b>No payments yet</b>Payments entered today will show here.</div>`}</div><div class="panel-sub" style="padding:0 18px 16px">Commissions ${Office.peso(dailySales.commissionTotal||0)} · card fees ${Office.peso(dailySales.cardFeeTotal||0)}</div></section>
    </div>
    <div class="grid-main" style="margin-top:15px;">
      <section class="panel"><div class="panel-head"><div><h2 class="panel-title">Booking status mix</h2><p class="panel-sub">Live today-by-status view</p></div></div><div class="low-stock-list">${statusRows}</div></section>
      <section class="panel"><div class="panel-head"><div><h2 class="panel-title">Top treatments today</h2><p class="panel-sub">Service mix across all bookings</p></div></div><div class="low-stock-list">${topServices.length?topServices.map(([service,count])=>`<div class="stock-row"><div class="stock-glyph">${escapeHTML(service.slice(0,1).toUpperCase())}</div><div class="stock-label"><b>${escapeHTML(service)}</b><span>${count} booked ${count===1?'session':'sessions'}</span></div><div class="stock-qty">${count}</div></div>`).join(''):`<div class="empty-state"><b>No treatments booked</b>Bookings will populate this list here.</div>`}</div></section>
    </div>
    <div class="grid-main" style="margin-top:15px;">
      <section class="panel"><div class="panel-head"><div><h2 class="panel-title">Inventory watch</h2><p class="panel-sub">Items nearing reorder level</p></div></div><div class="low-stock-list">${lowInventoryRows}</div></section>
      <section class="panel"><div class="panel-head"><div><h2 class="panel-title">Branch pulse</h2><p class="panel-sub">Operational volume by location</p></div></div><div class="low-stock-list">${branchPulse}</div></section>
    </div>
    <div class="grid-main" style="margin-top:15px;">
      <section class="panel"><div class="panel-head"><div><h2 class="panel-title">Sales leaders today</h2><p class="panel-sub">Paid services and credited service staff</p></div><button class="text-link" data-page="office-employees">Employee details →</button></div><div class="low-stock-list">${revenueServices.length?revenueServices.map(([service,total])=>`<div class="stock-row"><div class="stock-glyph">${escapeHTML(service.slice(0,1).toUpperCase())}</div><div class="stock-label"><b>${escapeHTML(service)}</b><span>Sales by treatment category</span></div><div class="stock-qty">${Office.peso(total)}</div></div>`).join(''):'<div class="empty-state"><b>No service sales yet</b>Payments will be summarized by service.</div>'}${revenueStaff.map(([name,total])=>`<div class="stock-row"><div class="stock-glyph">${escapeHTML(name.slice(0,1).toUpperCase())}</div><div class="stock-label"><b>${escapeHTML(name)}</b><span>Credited staff sales</span></div><div class="stock-qty">${Office.peso(total)}</div></div>`).join('')}</div></section>
      <section class="panel"><div class="panel-head"><div><h2 class="panel-title">Expenses today</h2><p class="panel-sub">${Object.keys(dailyExpenses.byCategory||{}).length} expense categories</p></div><button class="text-link" data-page="office-expenses">Open expenses →</button></div><div class="low-stock-list"><div class="stock-row"><div class="stock-glyph">₱</div><div class="stock-label"><b>Total expenses</b><span>Today across all branches</span></div><div class="stock-qty">${Office.peso(dailyExpenses.total||0)}</div></div>${Object.entries(dailyExpenses.byCategory||{}).map(([category,total])=>`<div class="stock-row"><div class="stock-glyph">${escapeHTML(category.slice(0,1).toUpperCase())}</div><div class="stock-label"><b>${escapeHTML(category)}</b><span>Recorded expenses</span></div><div class="stock-qty">${Office.peso(total)}</div></div>`).join('')}</div></section>
    </div>
    <div class="branch-strip">${branchSummary.join('')}</div>
    <div class="footer-note"><span>EL Glamorous Face and Body Clinic · Staff workspace</span><span>Bring out the beauty in you.</span></div>`;
  }

  function renderBookings() {
    const items=appointments.filter(a=>(statusFilter==='All statuses'||a.status===statusFilter)&&(branchFilter==='All branches'||a.branch===branchFilter)&&`${a.id} ${a.name} ${a.phone} ${a.service} ${a.branch}`.toLowerCase().includes(searchTerm.toLowerCase()));
    const actions=`<button class="btn btn-primary" data-action="new-booking">${icon.plus} Add appointment</button>`;
    return `${header('Booking desk','Appointments','Manage customer bookings and appointment status.',actions)}${demoBanner()}
      <section class="panel"><div class="toolbar"><label class="field-search">${icon.search}<input id="bookingSearch" type="search" value="${escapeHTML(searchTerm)}" placeholder="Search name, phone, service or ID…" aria-label="Search appointments"></label><select id="statusFilter" aria-label="Filter by status">${['All statuses',...STATUSES].map(s=>`<option ${statusFilter===s?'selected':''}>${s}</option>`).join('')}</select>${branchSelect('bookingBranchFilter',branchFilter)}</div>
      <div class="table-scroll"><table><thead><tr><th>Customer</th><th>Service</th><th>Branch</th><th>Date & time</th><th>Status</th><th>Manage</th></tr></thead><tbody>${items.length?items.sort((a,b)=>(a.date+a.time).localeCompare(b.date+b.time)).map(a=>`<tr><td><div class="table-primary">${escapeHTML(a.name)}</div><div class="table-secondary">${escapeHTML(a.phone)} · ${escapeHTML(a.id)}</div></td><td><div class="table-primary">${escapeHTML(a.service)}</div><div class="table-secondary">${escapeHTML(a.category)} · ${escapeHTML(a.source)}</div></td><td>${escapeHTML(a.branch)}</td><td><div class="table-primary">${escapeHTML(niceDate(a.date))}</div><div class="table-secondary">${timeLabel(a.time)}</div></td><td>${badge(a.status)}${a.paidAmount!=null?`<div class="table-secondary">Paid ${Office.peso(a.paidAmount)} · ${escapeHTML(a.paidMethod)}</div>`:''}</td><td><select class="table-action status-update" data-id="${escapeHTML(a.id)}" aria-label="Change status for ${escapeHTML(a.name)}">${STATUSES.map(s=>`<option ${a.status===s?'selected':''}>${s}</option>`).join('')}</select></td></tr>`).join(''):`<tr><td colspan="6"><div class="empty-state"><b>No bookings match</b>Try another search or filter.</div></td></tr>`}</tbody></table></div></section>
      <div class="footer-note"><span>${items.length} ${items.length===1?'appointment':'appointments'} shown</span><span>Changes are saved to the clinic database.</span></div>`;
  }
  function renderInventory() {
    const items=inventory.filter(i=>(inventoryBranchFilter==='All branches'||i.branch===inventoryBranchFilter)&&`${i.code} ${i.name} ${i.category} ${i.branch}`.toLowerCase().includes(searchTerm.toLowerCase()));
    const low=lowStock();
    return `${header('Stockroom','Inventory','Track clinic supplies by branch and adjust on-hand quantities.',`<button class="btn btn-primary" data-action="new-stock">${icon.plus} Add stock item</button>`)}${demoBanner()}
      ${low.length?`<div class="inventory-alert">${icon.alert}<span><b>${low.length} ${low.length===1?'item is':'items are'} at or below reorder point.</b> Review quantities and restock as needed.</span></div>`:''}
      <section class="panel" style="margin-top:16px"><div class="toolbar"><label class="field-search">${icon.search}<input id="inventorySearch" type="search" value="${escapeHTML(searchTerm)}" placeholder="Search product, category or ID…" aria-label="Search stock"></label>${branchSelect('inventoryBranchFilter',inventoryBranchFilter)}</div>
      <div class="table-scroll"><table style="min-width:700px"><thead><tr><th>Item</th><th>Category</th><th>Branch</th><th>On hand</th><th>Reorder at</th><th>Stock status</th><th>Action</th></tr></thead><tbody>${items.length?items.map(i=>{const isLow=Number(i.qty)<=Number(i.reorder);return `<tr><td><div class="table-primary">${escapeHTML(i.name)}</div><div class="table-secondary">${escapeHTML(i.code)}</div></td><td>${escapeHTML(i.category)}</td><td>${escapeHTML(i.branch)}</td><td><div class="table-primary">${escapeHTML(i.qty)} ${escapeHTML(i.unit)}</div></td><td>${escapeHTML(i.reorder)} ${escapeHTML(i.unit)}</td><td>${isLow?'<span class="status pending">Reorder</span>':'<span class="status confirmed">In stock</span>'}</td><td><button class="table-action" data-action="adjust-stock" data-id="${escapeHTML(i.id)}">Adjust stock</button></td></tr>`}).join(''):`<tr><td colspan="7"><div class="empty-state"><b>No stock items found</b>Try another search or branch.</div></td></tr>`}</tbody></table></div></section>
      <section class="panel" style="margin-top:16px"><div class="panel-head"><div><h2 class="panel-title">Stock movement audit</h2><p class="panel-sub">Latest ${stockMovements.length} inventory changes · reason and user recorded</p></div></div><div class="table-scroll"><table><thead><tr><th>Date & time</th><th>Item</th><th>Branch</th><th>Movement</th><th>Quantity</th><th>Reason</th><th>Recorded by</th></tr></thead><tbody>${stockMovements.length?stockMovements.map(m=>`<tr><td>${escapeHTML(new Date(m.date).toLocaleString('en-PH',{month:'short',day:'numeric',year:'numeric',hour:'numeric',minute:'2-digit'}))}</td><td>${escapeHTML(m.itemName)}</td><td>${escapeHTML(m.branch)}</td><td>${escapeHTML(m.type)}</td><td>${m.qty} ${escapeHTML(m.unit)}</td><td>${escapeHTML(m.note||'—')}</td><td>${escapeHTML(m.by||'—')}</td></tr>`).join(''):`<tr><td colspan="7"><div class="empty-state"><b>No stock movements yet</b>Adjustments and stock usage will be recorded here.</div></td></tr>`}</tbody></table></div></section>
      <div class="footer-note"><span>${items.length} stock ${items.length===1?'item':'items'} · ${low.length} at reorder point</span><span>Stock changes are recorded in the clinic database.</span></div>`;
  }
  function renderServices() {
    const money=n=>'₱'+Number(n).toLocaleString('en-PH',{minimumFractionDigits:2,maximumFractionDigits:2});
    const groups=['Face','Body','Hair','Nails'].map(category=>({category,items:serviceCatalog.filter(s=>s.category===category)}));
    const live=serviceCatalog.filter(s=>s.active).length, hidden=serviceCatalog.length-live;
    return `${header('Treatment menu','Service catalog','Add treatments, set durations and prices, or hide a treatment from booking.',`<button class="btn btn-primary" data-action="new-service">${icon.plus} Add treatment</button>`)}${demoBanner('Hidden treatments stay on past bookings but can’t be booked. Durations and prices show “To be confirmed” until you set them.')}
      <div class="service-grid">${groups.map(g=>`<article class="service-card"><div class="service-card-head"><h2>${escapeHTML(g.category)}</h2><span class="service-icon" aria-hidden="true">${categoryIcons[g.category]}</span></div>${g.items.length?g.items.map(item=>`<div class="service-item ${item.active?'':'hidden-service'}"><div><b>${escapeHTML(item.name)}</b><span>${item.durationMin?`${escapeHTML(item.durationMin)} min`:'Duration to be confirmed'}${item.active?'':' · <span class="status cancelled">Hidden from booking</span>'}</span></div><div class="service-actions"><span class="price-placeholder">${item.price!==null?money(item.price):'Price TBC'}</span><button class="link-action" data-action="edit-service" data-id="${escapeHTML(item.id)}" aria-label="Edit ${escapeHTML(item.name)}">Edit</button></div></div>`).join(''):'<div class="service-item"><span>No treatments in this category yet.</span></div>'}</article>`).join('')}</div>
      <div class="footer-note"><span>${live} bookable ${live===1?'treatment':'treatments'}${hidden?` · ${hidden} hidden`:''}</span><span>Changes appear on every booking form straight away.</span></div>`;
  }
  function openServiceModal(id=null) {
    const item=serviceCatalog.find(s=>s.id===id);
    openModal(`<div class="modal-head"><div><h2 id="modalTitle">${item?'Edit treatment':'Add treatment'}</h2><p>${item?'Changes apply to new bookings straight away.':'It becomes bookable at every branch straight away.'}</p></div><button class="modal-close" type="button" data-close aria-label="Close">×</button></div>
      <form id="serviceForm"><div class="modal-body"><div class="form-grid">
        <div class="form-field full"><label for="svcName">Treatment name *</label><input id="svcName" name="name" required maxlength="120" value="${escapeHTML(item?.name??'')}" placeholder="e.g. Hot Stone Massage"></div>
        <div class="form-field"><label for="svcCategory">Category *</label><select id="svcCategory" name="category" required>${['Face','Body','Hair','Nails'].map(c=>`<option ${item?.category===c?'selected':''}>${c}</option>`).join('')}</select></div>
        <div class="form-field"><label for="svcDuration">Duration (minutes)</label><input id="svcDuration" name="durationMin" type="number" min="5" max="600" step="5" value="${item?.durationMin??''}" placeholder="e.g. 60"></div>
        <div class="form-field"><label for="svcPrice">Price (₱)</label><input id="svcPrice" name="price" inputmode="decimal" value="${item?.price??''}" placeholder="Leave blank if not set"></div>
        ${item?`<div class="form-field"><label for="svcActive">Booking</label><select id="svcActive" name="active"><option value="1" ${item.active?'selected':''}>Can be booked</option><option value="" ${item.active?'':'selected'}>Hidden from booking</option></select></div>`:''}
      </div><div class="form-error" id="serviceError" role="alert"></div></div><div class="modal-actions"><button class="btn btn-secondary" type="button" data-close>Cancel</button><button class="btn btn-primary" type="submit">${item?'Save changes':'Add treatment'}</button></div></form>`);
    document.querySelectorAll('[data-close]').forEach(b=>b.addEventListener('click',closeModal));
    document.getElementById('serviceForm').addEventListener('submit',async e=>{e.preventDefault();const form=e.currentTarget,button=form.querySelector('button[type=submit]'),data=Object.fromEntries(new FormData(form).entries()),error=document.getElementById('serviceError');
      if(item) data.active=data.active==='1';
      error.classList.remove('show');button.disabled=true;
      try { await api(item?`services.php?id=${encodeURIComponent(item.id)}`:'services.php',{method:item?'PATCH':'POST',body:JSON.stringify(data)}); await loadServices(); closeModal(); render(); toast(item?'Treatment updated.':'Treatment added.'); }
      catch (err) { error.textContent=err.message; error.classList.add('show'); }
      finally { button.disabled=false; }
    });
  }
  // ---------- Staff accounts ----------
  function renderStaff() {
    const active=staffAccounts.filter(a=>a.active), staffCount=active.filter(a=>a.role==='staff').length, admins=active.filter(a=>a.role==='admin').length;
    const access=a=>a.role==='admin'?'<span class="mini-pill">Every area</span>':a.permissions.length?a.permissions.map(p=>`<span class="mini-pill" title="${escapeHTML(permissionLabels[p]||p)}">${escapeHTML((permissionLabels[p]||p).replace(/ \(.*\)$/,''))}</span>`).join(' '):'<span class="table-secondary">Front desk only</span>';
    return `${header('Team','Staff accounts','Add accounts, set branches, job titles and office access, reset passwords, or deactivate an account.',`<button class="btn btn-primary" data-action="new-account">${icon.plus} Add account</button>`)}${demoBanner('Deactivated accounts can’t sign in, and anyone signed in with one is signed out straight away. You can’t deactivate or demote your own account.')}
      <div class="stats">${statCard('Active staff',staffCount,'Branch staff accounts',icon.check)}${statCard('Administrators',admins,'Full access to every branch',icon.box)}${statCard('With office access',active.filter(a=>a.role==='staff'&&a.permissions.length).length,'Customers, sales, reports or expenses',icon.calendar)}${statCard('Deactivated',staffAccounts.length-active.length,'Can’t sign in',icon.alert)}</div>
      <section class="panel"><div class="table-scroll"><table><thead><tr><th>Name</th><th>Role</th><th>Job title</th><th>Branch</th><th>Office access</th><th>Status</th><th>Manage</th></tr></thead><tbody>${staffAccounts.length?staffAccounts.map(a=>`<tr><td><div class="table-primary">${escapeHTML(a.name)}${a.id===CURRENT_USER.id?' <span class="mini-pill">You</span>':''}</div><div class="table-secondary">${escapeHTML(a.email)}</div></td><td>${a.role==='admin'?'Admin':'Staff'}</td><td>${escapeHTML(a.jobTitle||'—')}</td><td>${escapeHTML(a.branch||'All branches')}</td><td style="max-width:280px">${access(a)}</td><td>${a.active?'<span class="status confirmed">Active</span>':'<span class="status cancelled">Deactivated</span>'}</td><td><button class="table-action" style="min-width:0" data-action="edit-account" data-id="${a.id}">Manage</button></td></tr>`).join(''):`<tr><td colspan="7"><div class="empty-state"><b>No accounts yet</b>Add the first staff account.</div></td></tr>`}</tbody></table></div></section>
      <div class="footer-note"><span>${staffAccounts.length} ${staffAccounts.length===1?'account':'accounts'} · ${active.length} active</span><span>Changes take effect on the person’s next click.</span></div>`;
  }
  function openAccountModal(id=null) {
    const a=staffAccounts.find(x=>String(x.id)===String(id));
    const isSelf=a&&a.id===CURRENT_USER.id;
    const permBoxes=Object.entries(permissionLabels).map(([key,label])=>`<label class="check-item"><input type="checkbox" name="perm" value="${escapeHTML(key)}" ${a?.permissions.includes(key)&&a.role!=='admin'?'checked':''}> ${escapeHTML(label)}</label>`).join('');
    openModal(`<div class="modal-head"><div><h2 id="modalTitle">${a?'Manage account':'Add account'}</h2><p>${a?escapeHTML(a.email):'They’ll sign in at the shared sign-in page and land on their own dashboard.'}</p></div><button class="modal-close" type="button" data-close aria-label="Close">×</button></div>
      <form id="accountForm"><div class="modal-body"><div class="form-grid">
        <div class="form-field full"><label for="accName">Full name *</label><input id="accName" name="name" required maxlength="120" value="${escapeHTML(a?.name??'')}"></div>
        ${a?'':'<div class="form-field full"><label for="accEmail">Email *</label><input id="accEmail" name="email" type="email" required maxlength="190" placeholder="name@example.com"></div>'}
        <div class="form-field"><label for="accRole">Role *</label><select id="accRole" name="role" ${isSelf?'disabled':''}><option value="staff" ${a?.role!=='admin'?'selected':''}>Staff (one branch)</option><option value="admin" ${a?.role==='admin'?'selected':''}>Admin (every branch)</option></select>${isSelf?'<div class="form-hint">You can’t change your own role.</div>':''}</div>
        <div class="form-field" data-staff-only><label for="accBranch">Branch *</label><select id="accBranch" name="branchId"><option value="">Choose a branch</option>${branches.map(b=>`<option value="${escapeHTML(b.id)}" ${a?.branchId===b.id?'selected':''}>${escapeHTML(b.name)}</option>`).join('')}</select></div>
        <div class="form-field full"><label for="accTitle">Job title</label><input id="accTitle" name="jobTitle" maxlength="80" value="${escapeHTML(a?.jobTitle??'')}" placeholder="e.g. Receptionist, Senior Hairdresser"></div>
        <div class="form-field full" data-staff-only><label>Office access</label><div class="check-list">${permBoxes}</div><div class="form-hint">Leave all unticked for front-desk access only (bookings, walk-ins, supplies).</div></div>
        <div class="form-field full" data-admin-only><div class="form-hint">Admins can open every area for every branch.</div></div>
        ${a?`<div class="form-field full"><label for="accActive">Status</label><select id="accActive" name="active" ${isSelf?'disabled':''}><option value="1" ${a.active?'selected':''}>Active — can sign in</option><option value="" ${a.active?'':'selected'}>Deactivated — can’t sign in</option></select></div>
        <div class="form-field full"><label class="check-item"><input type="checkbox" id="accReset" name="resetPassword" value="1"> Reset password</label></div>`:''}
        <div class="form-field full" ${a?'data-reset-only':''}><label for="accPassword">${a?'New password':'Password'}</label><input id="accPassword" name="password" type="text" autocomplete="new-password" minlength="8" maxlength="72" placeholder="Leave blank to generate one"><div class="form-hint">At least 8 characters. A generated password is shown once after saving.</div></div>
      </div><div class="form-error" id="accountError" role="alert"></div></div><div class="modal-actions"><button class="btn btn-secondary" type="button" data-close>Cancel</button><button class="btn btn-primary" type="submit">${a?'Save changes':'Create account'}</button></div></form>`);
    const form=document.getElementById('accountForm');
    const sync=()=>{const admin=form.elements.role.value==='admin';form.querySelectorAll('[data-staff-only]').forEach(el=>el.hidden=admin);form.querySelectorAll('[data-admin-only]').forEach(el=>el.hidden=!admin);form.querySelectorAll('[data-reset-only]').forEach(el=>el.hidden=!form.elements.resetPassword?.checked);};
    form.elements.role.addEventListener('change',sync); form.elements.resetPassword?.addEventListener('change',sync); sync();
    document.querySelectorAll('[data-close]').forEach(b=>b.addEventListener('click',closeModal));
    form.addEventListener('submit',async e=>{e.preventDefault();const button=form.querySelector('button[type=submit]'),error=document.getElementById('accountError');
      const data={name:form.elements.name.value,role:isSelf?a.role:form.elements.role.value,branchId:form.elements.branchId.value,jobTitle:form.elements.jobTitle.value,permissions:[...form.querySelectorAll('input[name=perm]:checked')].map(x=>x.value),password:form.elements.password.value};
      if(a){data.active=isSelf?true:form.elements.active.value==='1';data.resetPassword=form.elements.resetPassword.checked;if(!data.resetPassword)data.password='';}else data.email=form.elements.email.value;
      error.classList.remove('show');button.disabled=true;
      try {
        const res=await api(a?`staff.php?id=${a.id}`:'staff.php',{method:a?'PATCH':'POST',body:JSON.stringify(data)});
        await loadStaff(); render();
        if(res.password) showPassword(res.account,res.password); else { closeModal(); toast(a?'Account updated.':'Account created.'); }
      } catch (err) { error.textContent=err.message; error.classList.add('show'); }
      finally { button.disabled=false; }
    });
  }
  // Shown once: the server never returns this password again.
  function showPassword(account,password) {
    openModal(`<div class="modal-head"><div><h2 id="modalTitle">Password for ${escapeHTML(account.name)}</h2><p>Share it privately with them. It won’t be shown again.</p></div><button class="modal-close" type="button" data-close aria-label="Close">×</button></div>
      <div class="modal-body"><div class="form-field"><label>Email</label><div class="table-primary">${escapeHTML(account.email)}</div></div><div style="height:12px"></div><div class="form-field"><label>Password</label><div class="password-box">${escapeHTML(password)}</div></div></div>
      <div class="modal-actions"><button class="btn btn-primary" type="button" data-close>Done</button></div>`);
    document.querySelectorAll('[data-close]').forEach(b=>b.addEventListener('click',closeModal));
  }
  function renderBranches() {
    return `${header('Clinic locations','Branches','Contact details and opening hours for each clinic.',`<span class="mini-pill">${branches.length} LOCATIONS</span>`)}${demoBanner('Branch details are loaded from the clinic database. Please confirm Pajac and Cebu City hours with the team.')}
      <div class="branch-grid">${branches.map(b=>`<article class="branch-card"><div class="branch-card-top"><div><h2>${escapeHTML(b.name)}</h2><div class="branch-area">${escapeHTML(b.area)}</div></div><span class="mini-pill">Clinic</span></div><div class="branch-detail">${icon.pin}<span>${escapeHTML(b.address)}</span></div><div class="branch-detail">${icon.phone}<span>${b.phones.map(p=>`<a href="tel:${escapeHTML(p.replace(/[^+\d]/g,''))}">${escapeHTML(p)}</a>`).join('<br>')}</span></div><div class="hours-note">${icon.clock} &nbsp;${escapeHTML(b.hours)}</div></article>`).join('')}</div>
      <div class="footer-note"><span>Social · Facebook &amp; Instagram · @elglamteam</span><span>Branch details are loaded from the clinic database.</span></div>`;
  }
  const pageTitles={overview:'Overview',bookings:'Appointments',inventory:'Inventory',services:'Service catalog',branches:'Branches',staff:'Staff accounts'};
  function render() {
    document.getElementById('breadcrumb').textContent=pageTitles[activePage];
    document.querySelectorAll('[data-page]').forEach(el=>el.classList.toggle('active',el.dataset.page===activePage));
    const pending=pendingAppointments().length;
    ['pendingCount','mobilePendingCount'].forEach(id=>{const el=document.getElementById(id);if(el)el.textContent=pending;});
    if (Office.isOfficePage(activePage)) { Office.render(activePage, content); return; }
    content.innerHTML=({overview:renderOverview,bookings:renderBookings,inventory:renderInventory,services:renderServices,branches:renderBranches,staff:renderStaff}[activePage])();
    bindPageControls();
  }
  function bindPageControls() {
    const bs=document.getElementById('bookingSearch'); if(bs) bs.addEventListener('input',e=>{searchTerm=e.target.value; const pos=e.target.selectionStart; render(); const n=document.getElementById('bookingSearch');n.focus();n.setSelectionRange(pos,pos);});
    const bf=document.getElementById('bookingBranchFilter'); if(bf) bf.addEventListener('change',e=>{branchFilter=e.target.value;render();});
    const sf=document.getElementById('statusFilter'); if(sf) sf.addEventListener('change',e=>{statusFilter=e.target.value;render();});
    const is=document.getElementById('inventorySearch'); if(is) is.addEventListener('input',e=>{searchTerm=e.target.value; const pos=e.target.selectionStart; render(); const n=document.getElementById('inventorySearch');n.focus();n.setSelectionRange(pos,pos);});
    const ib=document.getElementById('inventoryBranchFilter'); if(ib) ib.addEventListener('change',e=>{inventoryBranchFilter=e.target.value;render();});
    content.querySelectorAll('.status-update').forEach(sel=>sel.addEventListener('change',e=>updateStatus(e.target.dataset.id,e.target.value)));
  }
  function navigate(page) { if(!pageTitles[page])return; activePage=page;searchTerm=''; document.getElementById('globalSearch').value=''; document.getElementById('mobileNav').classList.remove('open');document.getElementById('menuButton').setAttribute('aria-expanded','false');render();window.scrollTo({top:0,behavior:'smooth'}); }
  document.addEventListener('click',e=>{
    const nav=e.target.closest('[data-page]'); if(nav){navigate(nav.dataset.page);return;}
    const action=e.target.closest('[data-action]'); if(action){if(action.dataset.action==='new-booking')openBookingModal();if(action.dataset.action==='adjust-stock')openStockModal(action.dataset.id);if(action.dataset.action==='new-stock')openStockModal();if(action.dataset.action==='new-service')openServiceModal();if(action.dataset.action==='edit-service')openServiceModal(action.dataset.id);if(action.dataset.action==='new-account')openAccountModal();if(action.dataset.action==='edit-account')openAccountModal(action.dataset.id);return;}
    if(e.target.closest('#alertButton')){navigate('inventory');return;}
    const menuButton=e.target.closest('#menuButton'); if(menuButton){const panel=document.getElementById('mobileNav');const open=panel.classList.toggle('open');menuButton.setAttribute('aria-expanded',String(open));}
    if(e.target===document.getElementById('modalBackdrop'))closeModal();
  });
  document.getElementById('globalSearch').addEventListener('input',e=>{const query=e.target.value;if(activePage==='overview')activePage='bookings';searchTerm=query;render();const target=document.getElementById(activePage==='inventory'?'inventorySearch':'bookingSearch');if(target){target.value=query;target.focus();}});
  function toast(message) { const box=document.createElement('div');box.className='toast';box.textContent=message;document.getElementById('toastWrap').appendChild(box);setTimeout(()=>box.remove(),3000); }
  function openModal(html) {const backdrop=document.getElementById('modalBackdrop');document.getElementById('modal').innerHTML=html;backdrop.classList.add('open');document.body.style.overflow='hidden';const first=backdrop.querySelector('input,select,button');if(first)first.focus();}
  function closeModal() {document.getElementById('modalBackdrop').classList.remove('open');document.body.style.overflow='';}
  document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal();});
  async function updateStatus(id, status) {
    try { await api(`bookings.php?ref=${encodeURIComponent(id)}`, {method:'PATCH', body:JSON.stringify({status})}); toast(`Booking ${id} marked ${status.toLowerCase()}.`); }
    catch (e) { toast(e.message); }
    try { await loadAppointments(); } catch (e) { toast(e.message); }
    render();
  }
  function getBranchTakenTimes(branchName, date) {
    const chosenDate = date || isoToday;
    return appointments.filter(a => a.branch === branchName && a.date === chosenDate && !['Cancelled','No-show'].includes(a.status)).map(a => a.time);
  }
  function refreshBookingSlotOptions() {
    const form = document.getElementById('bookingForm');
    if (!form) return;
    const branch = form.elements.branch.value;
    const date = form.elements.date.value || isoToday;
    const timeSelect = form.elements.time;
    const message = document.getElementById('bookingSlotStatus');
    const taken = new Set(getBranchTakenTimes(branch, date).map(t => to24(t)));
    const options = TIME_SLOTS.filter(slot => !taken.has(to24(slot)));
    timeSelect.innerHTML = options.length ? options.map(slot => `<option value="${escapeHTML(slot)}">${escapeHTML(slot)}</option>`).join('') : '<option value="">No slots available</option>';
    timeSelect.disabled = !options.length;
    if (message) {
      if (!options.length) {
        message.textContent = `No open time slots remain for ${branch} on ${niceDate(date)}.`;
        message.classList.add('show');
      } else {
        message.textContent = `Available slots for ${branch} on ${niceDate(date)}.`;
        message.classList.remove('show');
      }
    }
  }
  function openBookingModal() {
    const serviceOptions=['Face','Body','Hair','Nails'].map(cat=>`<optgroup label="${cat}">${serviceCatalog.filter(s=>s.category===cat&&s.active).map(s=>`<option value="${escapeHTML(s.id)}">${escapeHTML(s.name)}</option>`).join('')}</optgroup>`).join('');
    openModal(`<div class="modal-head"><div><h2 id="modalTitle">Add appointment</h2><p>Create a booking for a customer.</p></div><button class="modal-close" type="button" data-close aria-label="Close">×</button></div>
      <form id="bookingForm"><div class="modal-body"><div class="form-grid">
        <div class="form-field"><label for="customerName">Customer name *</label><input id="customerName" name="name" required autocomplete="name" placeholder="Full name"></div>
        <div class="form-field"><label for="customerPhone">Mobile number *</label><input id="customerPhone" name="mobile" required autocomplete="tel" placeholder="09xx xxx xxxx"></div>
        <div class="form-field"><label for="bookingBranch">Branch *</label><select id="bookingBranch" name="branch" required>${branches.map(b=>`<option>${escapeHTML(b.name)}</option>`).join('')}</select></div>
        <div class="form-field"><label for="bookingService">Service *</label><select id="bookingService" name="serviceId" required>${serviceOptions}</select></div>
        <div class="form-field"><label for="bookingDate">Date *</label><input type="date" id="bookingDate" name="date" min="${isoToday}" value="${isoToday}" required></div>
        <div class="form-field"><label for="bookingTime">Time *</label><select id="bookingTime" name="time" required></select><div class="form-hint" id="bookingSlotStatus">Checking availability…</div></div>
        <div class="form-field full"><label for="bookingSource">Booked via *</label><select id="bookingSource" name="source"><option value="Online">Phone or online request</option><option value="Walk-in">Walk-in</option></select></div>
      </div><div class="form-error" id="bookingError" role="alert"></div></div><div class="modal-actions"><button class="btn btn-secondary" type="button" data-close>Cancel</button><button class="btn btn-primary" type="submit">Save appointment</button></div></form>`);
    const form = document.getElementById('bookingForm');
    const updateAvailability = () => refreshBookingSlotOptions();
    form.elements.branch.addEventListener('change', updateAvailability);
    form.elements.date.addEventListener('change', updateAvailability);
    updateAvailability();
    document.querySelectorAll('[data-close]').forEach(b=>b.addEventListener('click',closeModal));
    form.addEventListener('submit',async e=>{e.preventDefault();const button=form.querySelector('button[type=submit]'),data=Object.fromEntries(new FormData(form).entries()),error=document.getElementById('bookingError');
      const branchName = data.branch;
      const selectedDate = data.date || isoToday;
      const chosenSlot = data.time;
      if (!chosenSlot || getBranchTakenTimes(branchName, selectedDate).includes(to24(chosenSlot))) {
        error.textContent = `That branch/time is already booked. Please choose another time.`;
        error.classList.add('show');
        refreshBookingSlotOptions();
        return;
      }
      error.classList.remove('show');button.disabled=true;
      try { await api('bookings.php',{method:'POST',body:JSON.stringify(data)}); await loadAppointments(); closeModal(); navigate('bookings'); toast('Appointment added and marked pending.'); }
      catch (err) { error.textContent=err.message; error.classList.add('show'); if(err.status===409)refreshBookingSlotOptions(); }
      finally { button.disabled=false; }
    });
  }
  function openStockModal(id=null) {
    const item=inventory.find(i=>i.id===id);
    openModal(`<div class="modal-head"><div><h2 id="modalTitle">${item?'Adjust stock':'Add stock item'}</h2><p>${item?'Update the on-hand quantity for this branch.':'Add an item to a branch’s inventory.'}</p></div><button class="modal-close" type="button" data-close aria-label="Close">×</button></div>
      <form id="stockForm"><div class="modal-body"><div class="form-grid">
        ${item?`<div class="form-field full"><label>Item</label><input value="${escapeHTML(item.name)} · ${escapeHTML(item.branch)}" disabled></div>`:`<div class="form-field full"><label for="stockName">Item name *</label><input id="stockName" name="name" required placeholder="e.g. Facial cleanser"></div>`}
        ${item?`<div class="form-field"><label for="stockMode">Adjustment</label><select id="stockMode" name="mode"><option value="set">Set quantity to</option><option value="add">Add quantity</option><option value="remove">Remove quantity</option></select></div><div class="form-field"><label for="stockQty">Quantity *</label><input id="stockQty" name="qty" type="number" min="0" step="1" value="${item.qty}" required></div><div class="form-field full"><label for="stockNote">Reason for adjustment *</label><input id="stockNote" name="note" maxlength="255" required placeholder="e.g. Physical stock count correction"></div>`:`<div class="form-field"><label for="stockBranch">Branch *</label><select id="stockBranch" name="branch">${branches.map(b=>`<option>${escapeHTML(b.name)}</option>`).join('')}</select></div><div class="form-field"><label for="stockCategory">Category *</label><select id="stockCategory" name="category"><option>Face</option><option>Body</option><option>Hair</option><option>Nails</option><option>Clinic supplies</option></select></div><div class="form-field"><label for="stockQty">On-hand quantity *</label><input id="stockQty" name="qty" type="number" min="0" step="1" value="0" required></div><div class="form-field"><label for="stockReorder">Reorder at *</label><input id="stockReorder" name="reorder" type="number" min="0" step="1" value="5" required></div><div class="form-field"><label for="stockUnit">Unit *</label><input id="stockUnit" name="unit" value="units" required></div>`}
      </div><div class="form-error" id="stockError" role="alert"></div></div><div class="modal-actions"><button class="btn btn-secondary" type="button" data-close>Cancel</button><button class="btn btn-primary" type="submit">${item?'Save quantity':'Add item'}</button></div></form>`);
    document.querySelectorAll('[data-close]').forEach(b=>b.addEventListener('click',closeModal));
    document.getElementById('stockForm').addEventListener('submit',async e=>{e.preventDefault();const form=e.currentTarget,button=form.querySelector('button[type=submit]'),data=Object.fromEntries(new FormData(form).entries());
      const body=item?{action:'adjust',itemId:Number(item.id),mode:data.mode,qty:Number(data.qty),note:data.note.trim()}:{action:'create',name:data.name.trim(),category:data.category,branch:data.branch,qty:Number(data.qty),reorder:Number(data.reorder),unit:data.unit.trim()};
      const error=document.getElementById('stockError');error.classList.remove('show');button.disabled=true;
      try { await api('inventory.php',{method:'POST',body:JSON.stringify(body)}); await loadInventory(); closeModal(); render(); toast(item?'Stock quantity updated and logged.':'Stock item added.'); }
      catch (err) { error.textContent=err.message; error.classList.add('show'); }
      finally { button.disabled=false; }
    });
  }
  async function startWorkspace(user) {
    document.getElementById('profileInitials').textContent=user.name.split(/\s+/).map(w=>w[0]).join('').slice(0,2).toUpperCase();
    document.getElementById('profileName').textContent=user.name;
    document.getElementById('profileName').title=user.name;
    try {
      const [, , svc, br, , sales, expenses] = await Promise.all([
        loadAppointments(), loadInventory(), api('services.php?all=1'), api('branches.php'), loadStaff(),
        api(`payments.php?action=daily&date=${encodeURIComponent(isoToday)}`),
        api(`expenses.php?date=${encodeURIComponent(isoToday)}`)
      ]);
      serviceCatalog=svc.services; branches=br.branches; dailySales=sales; dailyExpenses=expenses;
      const branchLabel=document.querySelector('.branch-status strong');
      if(branchLabel)branchLabel.innerHTML=`<span class="dot"></span>${branches.length} clinic branches`;
    } catch (e) { toast(e.message); }
    // Office pages (admins have every permission, across all branches).
    Office.setup({ api, toast, user, isAdmin:true, branches:()=>branches });
    const officePages=Office.pagesFor(user);
    officePages.forEach(p=>{ pageTitles[p.key]=p.title; });
    if (officePages.length) {
      document.getElementById('officeLabel').hidden=false;
      document.getElementById('officeNav').innerHTML=officePages.map(p=>`<button class="nav-item" data-page="${p.key}">${p.icon}${escapeHTML(p.label)}</button>`).join('');
      document.getElementById('mobileOfficeNav').innerHTML=officePages.map(p=>`<button class="nav-item" data-page="${p.key}">${escapeHTML(p.label)}</button>`).join('');
    }
    document.getElementById('app').hidden=false;
    render();
  }
  document.getElementById('signOut').addEventListener('click',async()=>{
    try { await api('auth.php',{method:'POST',body:JSON.stringify({action:'logout'})}); } catch {}
    window.location.replace(LOGIN_URL+'?notice=signed_out');
  });
  // Inactivity sign-out. The server ends a session after SESSION_IDLE_MINUTES without activity;
  // activity on this page keeps it alive. When the timer runs out, the server is asked first,
  // because another open tab may have kept the session active.
  const IDLE_MS=<?= SESSION_IDLE_MINUTES ?>*60*1000;
  let idleTimer=null, lastKeepAlive=Date.now();
  function scheduleIdleCheck(ms){clearTimeout(idleTimer);idleTimer=setTimeout(checkIdle,ms);}
  async function checkIdle(){
    let res;
    try{res=await fetch(`${API}/auth.php?peek=1`,{credentials:'same-origin'});}catch{scheduleIdleCheck(60000);return;}
    if(res.ok){const {secondsLeft}=await res.json();scheduleIdleCheck(Math.max(secondsLeft,0)*1000+1000);return;}
    if(res.status===401){window.location.replace(LOGIN_URL+'?notice=idle');return;}
    scheduleIdleCheck(60000); // server error: check again shortly
  }
  function noteActivity(){
    scheduleIdleCheck(IDLE_MS);
    if(Date.now()-lastKeepAlive>2*60*1000){lastKeepAlive=Date.now();fetch(`${API}/auth.php`,{credentials:'same-origin'}).catch(()=>{});}
  }
  ['pointerdown','keydown','scroll','touchstart','mousemove'].forEach(type=>document.addEventListener(type,noteActivity,{passive:true}));
  scheduleIdleCheck(IDLE_MS);
  startWorkspace(CURRENT_USER);
</script>
</body>
</html>
